WITH with_windows AS (SELECT id, product_id, LAG(unit_price) OVER (PARTITION BY product_id ORDER BY quantity, id) prev_unit_price, LAG(quantity) OVER (PARTITION BY product_id ORDER BY quantity, id) prev_quantity, LEAD(quantity) OVER (PARTITION BY product_id ORDER BY quantity, id) next_quantity, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity, id) event_seq FROM order_items) SELECT s.id, s.product_id, s.prev_unit_price, s.prev_quantity, s.next_quantity, s.event_seq, (SELECT SUM(t2.unit_price) FROM order_items t2 WHERE t2.product_id = s.product_id) AS sum_order_item_unit_price FROM with_windows s ORDER BY next_quantity
